static void volvoxai_v1_affine_quantization_parameters_clear_parameters(
    VolvoxaiV1AffineQuantizationParameters* message) {
    const SynurangLiteAllocator* allocator =
        synurang_lite_allocator_or_default(message->_allocator);
    (void)allocator; /* Scalar-only oneofs own no allocations. */
    switch (message->which_parameters) {
        case 1:
            if (message->field_per_tensor) {
                volvoxai_v1_per_tensor_affine_quantization_free(message->field_per_tensor);
                synurang_lite_release(allocator, message->field_per_tensor);
                message->field_per_tensor = NULL;
            }
            break;
        case 2:
            if (message->field_per_axis) {
                volvoxai_v1_per_axis_affine_quantization_free(message->field_per_axis);
                synurang_lite_release(allocator, message->field_per_axis);
                message->field_per_axis = NULL;
            }
            break;
        default: break;
    }
    message->which_parameters = 0;
}
static void volvoxai_v1_create_graph_plan_request_clear_source(
    VolvoxaiV1CreateGraphPlanRequest* message) {
    const SynurangLiteAllocator* allocator =
        synurang_lite_allocator_or_default(message->_allocator);
    (void)allocator; /* Scalar-only oneofs own no allocations. */
    switch (message->which_source) {
        case 1:
            message->field_model_id = 0;
            break;
        case 2:
            if (message->field_graph) {
                volvoxai_v1_graph_planning_source_free(message->field_graph);
                synurang_lite_release(allocator, message->field_graph);
                message->field_graph = NULL;
            }
            break;
        default: break;
    }
    message->which_source = 0;
}
static void volvoxai_v1_create_tokenizer_request_clear_vocabulary(
    VolvoxaiV1CreateTokenizerRequest* message) {
    const SynurangLiteAllocator* allocator =
        synurang_lite_allocator_or_default(message->_allocator);
    (void)allocator; /* Scalar-only oneofs own no allocations. */
    switch (message->which_vocabulary) {
        case 1:
            if (message->field_tokens) {
                volvoxai_v1_tokenizer_vocabulary_free(message->field_tokens);
                synurang_lite_release(allocator, message->field_tokens);
                message->field_tokens = NULL;
            }
            break;
        case 2:
            synurang_lite_bytes_clear(allocator, &message->field_vocabulary_json);
            break;
        case 3:
            synurang_lite_bytes_clear(allocator, &message->field_vocabulary_binary);
            break;
        default: break;
    }
    message->which_vocabulary = 0;
}
