static SynurangLiteStatus volvoxai_v1_memory_capture_options_encode_into(
    const VolvoxaiV1MemoryCaptureOptions* message,
    SynurangLiteWriterInternal* writer) {
    SynurangLiteStatus status = SYNURANG_LITE_OK;
    size_t i;
    if (!message || !writer) return SYNURANG_LITE_INVALID_ARGUMENT;
    (void)status;
    if (message->field_protocol.len) {
        sl_write_length_delimited(
            writer,
            1,
            message->field_protocol.data,
            message->field_protocol.len);
    }
    if (message->field_include_resource_inventory) {
        sl_write_bool(
            writer, 2, message->field_include_resource_inventory);
    }
    if (message->field_include_domain_attestation) {
        sl_write_bool(
            writer, 3, message->field_include_domain_attestation);
    }
    if (message->field_requested_envelopes.len) {
        SynurangLiteWriterInternal packed;
        sl_writer_init(&packed, message->_allocator);
        for (i = 0; i < message->field_requested_envelopes.len; ++i) {
            sl_write_enum_raw(
                &packed, message->field_requested_envelopes.data[i]);
        }
        if (packed.status == SYNURANG_LITE_OK) {
            sl_write_length_delimited(writer, 4, packed.data, packed.len);
        }
        status = packed.status;
        sl_writer_discard(&packed);
        if (status != SYNURANG_LITE_OK) return status;
    }
    if (message->has_sampling_interval_nanoseconds) {
        sl_write_uint64(
            writer, 5, message->field_sampling_interval_nanoseconds);
    }
    if (message->has_max_periodic_snapshots) {
        sl_write_uint32(
            writer, 6, message->field_max_periodic_snapshots);
    }
    (void)i;
    return writer->status;
}

