static SynurangLiteStatus volvoxai_v1_tensor_encode_into(
    const VolvoxaiV1Tensor* message,
    SynurangLiteWriterInternal* writer) {
    SynurangLiteStatus status = SYNURANG_LITE_OK;
    size_t i;
    if (!message || !writer) return SYNURANG_LITE_INVALID_ARGUMENT;
    (void)status;
    if (message->field_name.len) {
        sl_write_length_delimited(
            writer,
            1,
            message->field_name.data,
            message->field_name.len);
    }
    if (message->field_shape.len) {
        SynurangLiteWriterInternal packed;
        sl_writer_init(&packed, message->_allocator);
        for (i = 0; i < message->field_shape.len; ++i) {
            sl_write_int64_raw(
                &packed, message->field_shape.data[i]);
        }
        if (packed.status == SYNURANG_LITE_OK) {
            sl_write_length_delimited(writer, 2, packed.data, packed.len);
        }
        status = packed.status;
        sl_writer_discard(&packed);
        if (status != SYNURANG_LITE_OK) return status;
    }
    if (message->field_dtype != 0) {
        sl_write_enum(
            writer, 3, message->field_dtype);
    }
    if (message->field_location != 0) {
        sl_write_enum(
            writer, 4, message->field_location);
    }
    if (message->which_payload == 5) {
        sl_write_length_delimited(
            writer,
            5,
            message->field_inline.data,
            message->field_inline.len);
    }
    if (message->which_payload == 6) {
        uint8_t* nested = NULL;
        size_t nested_len = 0;
        status = volvoxai_v1_buffer_view_encode(
            message->field_view, &nested, &nested_len);
        if (status != SYNURANG_LITE_OK) return status;
        sl_write_length_delimited(writer, 6, nested, nested_len);
        synurang_lite_release(message->field_view->_allocator, nested);
    }
    (void)i;
    return writer->status;
}

