static SynurangLiteStatus volvoxai_v1_batch_dispatch_work_merge_reader(
    VolvoxaiV1BatchDispatchWork* message,
    SynurangLiteReaderInternal* reader,
    unsigned int message_depth) {
    SynurangLiteStatus status = SYNURANG_LITE_OK;
    uint32_t field_number;
    uint8_t wire_type;
    int tag_result;
    if (!message || !reader) return SYNURANG_LITE_INVALID_ARGUMENT;
    if (message_depth > SYNURANG_LITE_MAX_MESSAGE_DEPTH) {
        return SYNURANG_LITE_MALFORMED;
    }
    (void)status;
    while ((tag_result = sl_read_tag(reader, &field_number, &wire_type)) > 0) {
        switch (field_number) {
            case 1:
                if (!sl_read_uint32(
                        reader, wire_type, &message->field_work_id)) break;
                break;
            case 2:
                if (!sl_read_uint32(
                        reader, wire_type, &message->field_rows)) break;
                break;
            case 3:
                if (!sl_read_sint32(
                        reader, wire_type, &message->field_lane)) break;
                break;
            case 4:
                if (!sl_read_uint32(
                        reader, wire_type, &message->field_lane_generation)) break;
                break;
            case 5:
                if (!sl_read_uint32(
                        reader, wire_type, &message->field_position)) break;
                break;
            case 6:
                if (!sl_read_uint32(
                        reader, wire_type, &message->field_tokens)) break;
                break;
            case 7:
                if (!sl_read_uint32(
                        reader, wire_type, &message->field_kv_length)) break;
                break;
            case 8:
            {
                void* appended;
                if (wire_type == 2) {
                    const uint8_t* packed_data;
                    size_t packed_len;
                    SynurangLiteReaderInternal packed;
                    if (!sl_read_slice(reader, &packed_data, &packed_len)) break;
                    sl_reader_init(&packed, packed_data, packed_len);
                    while (packed.pos < packed.len) {
                        status = sl_array_append(
                            message->_allocator,
                            (void**)&message->field_pages.data,
                            &message->field_pages.len,
                            &message->field_pages.cap,
                            sizeof(*message->field_pages.data),
                            &appended);
                        if (status != SYNURANG_LITE_OK) return status;
                        if (!sl_read_sint32_raw(
                                &packed,
                                (int32_t*)appended)) break;
                    }
                    if (packed.status != SYNURANG_LITE_OK || packed.pos != packed.len) {
                        reader->status = packed.status == SYNURANG_LITE_OK
                            ? SYNURANG_LITE_MALFORMED : packed.status;
                    }
                } else {
                    status = sl_array_append(
                        message->_allocator,
                        (void**)&message->field_pages.data,
                        &message->field_pages.len,
                        &message->field_pages.cap,
                        sizeof(*message->field_pages.data),
                        &appended);
                    if (status != SYNURANG_LITE_OK) return status;
                    if (!sl_read_sint32(
                            reader,
                            wire_type,
                            (int32_t*)appended)) break;
                }
                break;
            }
            case 9:
                if (!sl_read_uint32(
                        reader, wire_type, &message->field_page_tokens)) break;
                break;
            case 10:
                if (!sl_read_uint32(
                        reader, wire_type, &message->field_generated)) break;
                break;
            case 11:
                if (!sl_read_bool(
                        reader, wire_type, &message->field_padding)) break;
                break;
            case 12:
            {
                const uint8_t* value_data;
                size_t value_len;
                if (!sl_expect_wire(reader, wire_type, 2) ||
                    !sl_read_slice(reader, &value_data, &value_len)) break;
                status = synurang_lite_bytes_assign(
                    message->_allocator,
                    &message->field_payload,
                    value_data,
                    value_len);
                if (status != SYNURANG_LITE_OK) return status;
                break;
            }
            case 13:
            {
                const uint8_t* value_data;
                size_t value_len;
                VolvoxaiV1Tensor* item;
                void* appended;
                if (!sl_expect_wire(reader, wire_type, 2) ||
                    !sl_read_slice(reader, &value_data, &value_len)) break;
                status = sl_array_append(
                    message->_allocator,
                    (void**)&message->field_inputs.data,
                    &message->field_inputs.len,
                    &message->field_inputs.cap,
                    sizeof(*message->field_inputs.data),
                    &appended);
                if (status != SYNURANG_LITE_OK) return status;
                item = (VolvoxaiV1Tensor*)appended;
                volvoxai_v1_tensor_init_with_allocator(item, message->_allocator);
                {
                    SynurangLiteReaderInternal value_reader;
                    sl_reader_init(&value_reader, value_data, value_len);
                    status = volvoxai_v1_tensor_merge_reader(
                        item, &value_reader, message_depth + 1);
                }
                if (status != SYNURANG_LITE_OK) return status;
                break;
            }
            default:
                if (wire_type == 4 || !sl_skip_field(reader, field_number, wire_type)) {
                    reader->status = SYNURANG_LITE_MALFORMED;
                }
                break;
        }
        if (reader->status != SYNURANG_LITE_OK) break;
    }
    if (tag_result < 0 || reader->status != SYNURANG_LITE_OK) return reader->status;
    return reader->pos == reader->len ? SYNURANG_LITE_OK : SYNURANG_LITE_MALFORMED;
}

