VolvoxaiV1GraphTensorRef* volvoxai_v1_execution_slice_add_changed_inputs(
    VolvoxaiV1ExecutionSlice* message) {
    const SynurangLiteAllocator* allocator;
    VolvoxaiV1GraphTensorRef* grown;
    size_t capacity;

    if (!message) return NULL;
    allocator = synurang_lite_allocator_or_default(message->_allocator);
    if (message->field_changed_inputs.len == message->field_changed_inputs.cap) {
        /* The allocator has no realloc, so growth allocates, copies, frees.
         * Doubling keeps repeated appends amortized. */
        capacity = message->field_changed_inputs.cap ? message->field_changed_inputs.cap * 2u : 4u;
        if (capacity < message->field_changed_inputs.cap ||
            capacity > SIZE_MAX / sizeof(*grown)) return NULL;
        grown = (VolvoxaiV1GraphTensorRef*)allocator->allocate(
            allocator->context, sizeof(*grown) * capacity);
        if (!grown) return NULL;
        memset(grown, 0, sizeof(*grown) * capacity);
        if (message->field_changed_inputs.len) {
            memcpy(grown, message->field_changed_inputs.data,
                   sizeof(*grown) * message->field_changed_inputs.len);
        }
        synurang_lite_release(allocator, message->field_changed_inputs.data);
        message->field_changed_inputs.data = grown;
        message->field_changed_inputs.cap = capacity;
    }
    {
        VolvoxaiV1GraphTensorRef* slot =
            &message->field_changed_inputs.data[message->field_changed_inputs.len];
        memset(slot, 0, sizeof(*slot));
        volvoxai_v1_graph_tensor_ref_init_with_allocator(slot, allocator);
        message->field_changed_inputs.len++;
        return slot;
    }
}
