    volvoxai_v1_graph_definition_init_with_allocator(&temporary, message->_allocator);
    sl_reader_init(&reader, data, len);
    status = volvoxai_v1_graph_definition_merge_reader(&temporary, &reader, 0);
    if (status != SYNURANG_LITE_OK) {
        volvoxai_v1_graph_definition_free(&temporary);
        return status;
    }
    volvoxai_v1_graph_definition_free(message);
