SynurangLiteBytes* volvoxai_v1_load_model_request_add_weight_paths(
    VolvoxaiV1LoadModelRequest* message) {
    const SynurangLiteAllocator* allocator;
    SynurangLiteBytes* grown;
    size_t capacity;

    if (!message) return NULL;
    allocator = synurang_lite_allocator_or_default(message->_allocator);
    if (message->field_weight_paths.len == message->field_weight_paths.cap) {
        /* The allocator has no realloc, so growth allocates, copies, frees.
         * Doubling keeps repeated appends amortized. */
        capacity = message->field_weight_paths.cap ? message->field_weight_paths.cap * 2u : 4u;
        if (capacity < message->field_weight_paths.cap ||
            capacity > SIZE_MAX / sizeof(*grown)) return NULL;
        grown = (SynurangLiteBytes*)allocator->allocate(
            allocator->context, sizeof(*grown) * capacity);
        if (!grown) return NULL;
        memset(grown, 0, sizeof(*grown) * capacity);
        if (message->field_weight_paths.len) {
            memcpy(grown, message->field_weight_paths.data,
                   sizeof(*grown) * message->field_weight_paths.len);
        }
        synurang_lite_release(allocator, message->field_weight_paths.data);
        message->field_weight_paths.data = grown;
        message->field_weight_paths.cap = capacity;
    }
    {
        SynurangLiteBytes* slot =
            &message->field_weight_paths.data[message->field_weight_paths.len];
        memset(slot, 0, sizeof(*slot));
        message->field_weight_paths.len++;
        return slot;
    }
}
