static SynurangLiteStatus volvoxai_v1_memory_envelope_evidence_merge_reader(
    VolvoxaiV1MemoryEnvelopeEvidence* message,
    SynurangLiteReaderInternal* reader,
    unsigned int message_depth) {
    SynurangLiteStatus status = SYNURANG_LITE_OK;
    uint32_t field_number;
    uint8_t wire_type;
    int tag_result;
    if (!message || !reader) return SYNURANG_LITE_INVALID_ARGUMENT;
    if (message_depth > SYNURANG_LITE_MAX_MESSAGE_DEPTH) {
        return SYNURANG_LITE_MALFORMED;
    }
    (void)status;
    while ((tag_result = sl_read_tag(reader, &field_number, &wire_type)) > 0) {
        switch (field_number) {
            case 1:
                if (!sl_read_enum(
                        reader, wire_type, &message->field_kind)) break;
                break;
            case 2:
            {
                const uint8_t* value_data;
                size_t value_len;
                if (!sl_expect_wire(reader, wire_type, 2) ||
                    !sl_read_slice(reader, &value_data, &value_len)) break;
                if (!message->field_bytes) {
                    message->field_bytes =
                        (VolvoxaiV1MemoryByteSize*)message->_allocator->allocate(
                            message->_allocator->context,
                            sizeof(*message->field_bytes));
                    if (!message->field_bytes) return SYNURANG_LITE_OUT_OF_MEMORY;
                    volvoxai_v1_memory_byte_size_init_with_allocator(
                        message->field_bytes, message->_allocator);
                }
                status = volvoxai_v1_memory_byte_size_merge_at_depth(
                    message->field_bytes, value_data, value_len,
                    message_depth + 1);
                if (status != SYNURANG_LITE_OK) return status;
                break;
            }
            case 3:
                if (!sl_read_enum(
                        reader, wire_type, &message->field_source)) break;
                break;
            case 4:
                if (!sl_read_enum(
                        reader, wire_type, &message->field_value_relation)) break;
                break;
            case 5:
                if (!sl_read_enum(
                        reader, wire_type, &message->field_temporal_coverage)) break;
                break;
            case 6:
            {
                const uint8_t* value_data;
                size_t value_len;
                if (!sl_expect_wire(reader, wire_type, 2) ||
                    !sl_read_slice(reader, &value_data, &value_len)) break;
                status = synurang_lite_bytes_assign(
                    message->_allocator,
                    &message->field_sampler,
                    value_data,
                    value_len);
                if (status != SYNURANG_LITE_OK) return status;
                break;
            }
            default:
                if (wire_type == 4 || !sl_skip_field(reader, field_number, wire_type)) {
                    reader->status = SYNURANG_LITE_MALFORMED;
                }
                break;
        }
        if (reader->status != SYNURANG_LITE_OK) break;
    }
    if (tag_result < 0 || reader->status != SYNURANG_LITE_OK) return reader->status;
    return reader->pos == reader->len ? SYNURANG_LITE_OK : SYNURANG_LITE_MALFORMED;
}

