float* volvoxai_v1_per_axis_affine_quantization_add_scales(
    VolvoxaiV1PerAxisAffineQuantization* message) {
    const SynurangLiteAllocator* allocator;
    float* grown;
    size_t capacity;

    if (!message) return NULL;
    allocator = synurang_lite_allocator_or_default(message->_allocator);
    if (message->field_scales.len == message->field_scales.cap) {
        /* The allocator has no realloc, so growth allocates, copies, frees.
         * Doubling keeps repeated appends amortized. */
        capacity = message->field_scales.cap ? message->field_scales.cap * 2u : 4u;
        if (capacity < message->field_scales.cap ||
            capacity > SIZE_MAX / sizeof(*grown)) return NULL;
        grown = (float*)allocator->allocate(
            allocator->context, sizeof(*grown) * capacity);
        if (!grown) return NULL;
        memset(grown, 0, sizeof(*grown) * capacity);
        if (message->field_scales.len) {
            memcpy(grown, message->field_scales.data,
                   sizeof(*grown) * message->field_scales.len);
        }
        synurang_lite_release(allocator, message->field_scales.data);
        message->field_scales.data = grown;
        message->field_scales.cap = capacity;
    }
    {
        float* slot =
            &message->field_scales.data[message->field_scales.len];
        memset(slot, 0, sizeof(*slot));
        message->field_scales.len++;
        return slot;
    }
}
