static SynurangLiteStatus volvoxai_v1_resolved_graph_tensor_merge_reader(
    VolvoxaiV1ResolvedGraphTensor* message,
    SynurangLiteReaderInternal* reader,
    unsigned int message_depth) {
    SynurangLiteStatus status = SYNURANG_LITE_OK;
    uint32_t field_number;
    uint8_t wire_type;
    int tag_result;
    if (!message || !reader) return SYNURANG_LITE_INVALID_ARGUMENT;
    if (message_depth > SYNURANG_LITE_MAX_MESSAGE_DEPTH) {
        return SYNURANG_LITE_MALFORMED;
    }
    (void)status;
    while ((tag_result = sl_read_tag(reader, &field_number, &wire_type)) > 0) {
        switch (field_number) {
            case 1:
                if (!sl_read_uint32(
                        reader, wire_type, &message->field_tensor_index)) break;
                break;
            case 2:
            {
                const uint8_t* value_data;
                size_t value_len;
                if (!sl_expect_wire(reader, wire_type, 2) ||
                    !sl_read_slice(reader, &value_data, &value_len)) break;
                status = synurang_lite_bytes_assign(
                    message->_allocator,
                    &message->field_name,
                    value_data,
                    value_len);
                if (status != SYNURANG_LITE_OK) return status;
                break;
            }
            case 3:
                if (!sl_read_enum(
                        reader, wire_type, &message->field_kind)) break;
                break;
            case 4:
                if (!sl_read_enum(
                        reader, wire_type, &message->field_dtype)) break;
                break;
            case 5:
            {
                void* appended;
                if (wire_type == 2) {
                    const uint8_t* packed_data;
                    size_t packed_len;
                    SynurangLiteReaderInternal packed;
                    if (!sl_read_slice(reader, &packed_data, &packed_len)) break;
                    sl_reader_init(&packed, packed_data, packed_len);
                    while (packed.pos < packed.len) {
                        status = sl_array_append(
                            message->_allocator,
                            (void**)&message->field_shape.data,
                            &message->field_shape.len,
                            &message->field_shape.cap,
                            sizeof(*message->field_shape.data),
                            &appended);
                        if (status != SYNURANG_LITE_OK) return status;
                        if (!sl_read_int64_raw(
                                &packed,
                                (int64_t*)appended)) break;
                    }
                    if (packed.status != SYNURANG_LITE_OK || packed.pos != packed.len) {
                        reader->status = packed.status == SYNURANG_LITE_OK
                            ? SYNURANG_LITE_MALFORMED : packed.status;
                    }
                } else {
                    status = sl_array_append(
                        message->_allocator,
                        (void**)&message->field_shape.data,
                        &message->field_shape.len,
                        &message->field_shape.cap,
                        sizeof(*message->field_shape.data),
                        &appended);
                    if (status != SYNURANG_LITE_OK) return status;
                    if (!sl_read_int64(
                            reader,
                            wire_type,
                            (int64_t*)appended)) break;
                }
                break;
            }
            case 6:
                if (!sl_read_uint64(
                        reader, wire_type, &message->field_element_count)) break;
                break;
            case 7:
                if (!sl_read_uint64(
                        reader, wire_type, &message->field_byte_size)) break;
                break;
            case 8:
            {
                const uint8_t* value_data;
                size_t value_len;
                if (!sl_expect_wire(reader, wire_type, 2) ||
                    !sl_read_slice(reader, &value_data, &value_len)) break;
                if (!message->field_quantization) {
                    message->field_quantization =
                        (VolvoxaiV1AffineQuantizationParameters*)message->_allocator->allocate(
                            message->_allocator->context,
                            sizeof(*message->field_quantization));
                    if (!message->field_quantization) return SYNURANG_LITE_OUT_OF_MEMORY;
                    volvoxai_v1_affine_quantization_parameters_init_with_allocator(
                        message->field_quantization, message->_allocator);
                }
                status = volvoxai_v1_affine_quantization_parameters_merge_at_depth(
                    message->field_quantization, value_data, value_len,
                    message_depth + 1);
                if (status != SYNURANG_LITE_OK) return status;
                break;
            }
            case 9:
            {
                const uint8_t* value_data;
                size_t value_len;
                if (!sl_expect_wire(reader, wire_type, 2) ||
                    !sl_read_slice(reader, &value_data, &value_len)) break;
                if (!message->field_storage_alias_root) {
                    message->field_storage_alias_root =
                        (VolvoxaiV1GraphTensorRef*)message->_allocator->allocate(
                            message->_allocator->context,
                            sizeof(*message->field_storage_alias_root));
                    if (!message->field_storage_alias_root) return SYNURANG_LITE_OUT_OF_MEMORY;
                    volvoxai_v1_graph_tensor_ref_init_with_allocator(
                        message->field_storage_alias_root, message->_allocator);
                }
                status = volvoxai_v1_graph_tensor_ref_merge_at_depth(
                    message->field_storage_alias_root, value_data, value_len,
                    message_depth + 1);
                if (status != SYNURANG_LITE_OK) return status;
                break;
            }
            default:
                if (wire_type == 4 || !sl_skip_field(reader, field_number, wire_type)) {
                    reader->status = SYNURANG_LITE_MALFORMED;
                }
                break;
        }
        if (reader->status != SYNURANG_LITE_OK) break;
    }
    if (tag_result < 0 || reader->status != SYNURANG_LITE_OK) return reader->status;
    return reader->pos == reader->len ? SYNURANG_LITE_OK : SYNURANG_LITE_MALFORMED;
}

