static SynurangLiteStatus volvoxai_v1_result_info_merge_reader(
    VolvoxaiV1ResultInfo* message,
    SynurangLiteReaderInternal* reader,
    unsigned int message_depth) {
    SynurangLiteStatus status = SYNURANG_LITE_OK;
    uint32_t field_number;
    uint8_t wire_type;
    int tag_result;
    if (!message || !reader) return SYNURANG_LITE_INVALID_ARGUMENT;
    if (message_depth > SYNURANG_LITE_MAX_MESSAGE_DEPTH) {
        return SYNURANG_LITE_MALFORMED;
    }
    (void)status;
    while ((tag_result = sl_read_tag(reader, &field_number, &wire_type)) > 0) {
        switch (field_number) {
            case 1:
                if (!sl_read_int64(
                        reader, wire_type, &message->field_result_id)) break;
                break;
            case 2:
                if (!sl_read_uint64(
                        reader, wire_type, &message->field_execution_id)) break;
                break;
            case 3:
            {
                const uint8_t* value_data;
                size_t value_len;
                VolvoxaiV1TensorInfo* item;
                void* appended;
                if (!sl_expect_wire(reader, wire_type, 2) ||
                    !sl_read_slice(reader, &value_data, &value_len)) break;
                status = sl_array_append(
                    message->_allocator,
                    (void**)&message->field_outputs.data,
                    &message->field_outputs.len,
                    &message->field_outputs.cap,
                    sizeof(*message->field_outputs.data),
                    &appended);
                if (status != SYNURANG_LITE_OK) return status;
                item = (VolvoxaiV1TensorInfo*)appended;
                volvoxai_v1_tensor_info_init_with_allocator(item, message->_allocator);
                {
                    SynurangLiteReaderInternal value_reader;
                    sl_reader_init(&value_reader, value_data, value_len);
                    status = volvoxai_v1_tensor_info_merge_reader(
                        item, &value_reader, message_depth + 1);
                }
                if (status != SYNURANG_LITE_OK) return status;
                break;
            }
            case 4:
            {
                const uint8_t* value_data;
                size_t value_len;
                if (!sl_expect_wire(reader, wire_type, 2) ||
                    !sl_read_slice(reader, &value_data, &value_len)) break;
                if (!message->field_report) {
                    message->field_report =
                        (VolvoxaiV1OperationReport*)message->_allocator->allocate(
                            message->_allocator->context,
                            sizeof(*message->field_report));
                    if (!message->field_report) return SYNURANG_LITE_OUT_OF_MEMORY;
                    volvoxai_v1_operation_report_init_with_allocator(
                        message->field_report, message->_allocator);
                }
                status = volvoxai_v1_operation_report_merge_at_depth(
                    message->field_report, value_data, value_len,
                    message_depth + 1);
                if (status != SYNURANG_LITE_OK) return status;
                break;
            }
            case 5:
                if (!sl_read_enum(
                        reader, wire_type, &message->field_state)) break;
                break;
            default:
                if (wire_type == 4 || !sl_skip_field(reader, field_number, wire_type)) {
                    reader->status = SYNURANG_LITE_MALFORMED;
                }
                break;
        }
        if (reader->status != SYNURANG_LITE_OK) break;
    }
    if (tag_result < 0 || reader->status != SYNURANG_LITE_OK) return reader->status;
    return reader->pos == reader->len ? SYNURANG_LITE_OK : SYNURANG_LITE_MALFORMED;
}

SynurangLiteStatus volvoxai_v1_result_info_decode(
    VolvoxaiV1ResultInfo* message,
    const uint8_t* data,
    size_t len) {
    VolvoxaiV1ResultInfo temporary;
    SynurangLiteReaderInternal reader;
    SynurangLiteStatus status;
    if (!message || (!data && len != 0)) return SYNURANG_LITE_INVALID_ARGUMENT;
    volvoxai_v1_result_info_init_with_allocator(&temporary, message->_allocator);
    sl_reader_init(&reader, data, len);
    status = volvoxai_v1_result_info_merge_reader(&temporary, &reader, 0);
    if (status != SYNURANG_LITE_OK) {
        volvoxai_v1_result_info_free(&temporary);
        return status;
    }
    volvoxai_v1_result_info_free(message);
    *message = temporary;
    return SYNURANG_LITE_OK;
}
VolvoxaiV1TensorInfo* volvoxai_v1_result_info_add_outputs(
    VolvoxaiV1ResultInfo* message) {
    const SynurangLiteAllocator* allocator;
    VolvoxaiV1TensorInfo* grown;
    size_t capacity;

    if (!message) return NULL;
    allocator = synurang_lite_allocator_or_default(message->_allocator);
    if (message->field_outputs.len == message->field_outputs.cap) {
        /* The allocator has no realloc, so growth allocates, copies, frees.
         * Doubling keeps repeated appends amortized. */
        capacity = message->field_outputs.cap ? message->field_outputs.cap * 2u : 4u;
        if (capacity < message->field_outputs.cap ||
            capacity > SIZE_MAX / sizeof(*grown)) return NULL;
        grown = (VolvoxaiV1TensorInfo*)allocator->allocate(
            allocator->context, sizeof(*grown) * capacity);
        if (!grown) return NULL;
        memset(grown, 0, sizeof(*grown) * capacity);
        if (message->field_outputs.len) {
            memcpy(grown, message->field_outputs.data,
                   sizeof(*grown) * message->field_outputs.len);
        }
        synurang_lite_release(allocator, message->field_outputs.data);
        message->field_outputs.data = grown;
        message->field_outputs.cap = capacity;
    }
    {
        VolvoxaiV1TensorInfo* slot =
            &message->field_outputs.data[message->field_outputs.len];
        memset(slot, 0, sizeof(*slot));
        volvoxai_v1_tensor_info_init_with_allocator(slot, allocator);
        message->field_outputs.len++;
        return slot;
    }
}

