VolvoxaiV1Tensor* volvoxai_v1_safetensors_content_add_tensors(
    VolvoxaiV1SafetensorsContent* message) {
    const SynurangLiteAllocator* allocator;
    VolvoxaiV1Tensor* grown;
    size_t capacity;

    if (!message) return NULL;
    allocator = synurang_lite_allocator_or_default(message->_allocator);
    if (message->field_tensors.len == message->field_tensors.cap) {
        /* The allocator has no realloc, so growth allocates, copies, frees.
         * Doubling keeps repeated appends amortized. */
        capacity = message->field_tensors.cap ? message->field_tensors.cap * 2u : 4u;
        if (capacity < message->field_tensors.cap ||
            capacity > SIZE_MAX / sizeof(*grown)) return NULL;
        grown = (VolvoxaiV1Tensor*)allocator->allocate(
            allocator->context, sizeof(*grown) * capacity);
        if (!grown) return NULL;
        memset(grown, 0, sizeof(*grown) * capacity);
        if (message->field_tensors.len) {
            memcpy(grown, message->field_tensors.data,
                   sizeof(*grown) * message->field_tensors.len);
        }
        synurang_lite_release(allocator, message->field_tensors.data);
        message->field_tensors.data = grown;
        message->field_tensors.cap = capacity;
    }
    {
        VolvoxaiV1Tensor* slot =
            &message->field_tensors.data[message->field_tensors.len];
        memset(slot, 0, sizeof(*slot));
        volvoxai_v1_tensor_init_with_allocator(slot, allocator);
        message->field_tensors.len++;
        return slot;
    }
}

