VolvoxaiV1ShapeDomainFact* volvoxai_v1_shape_domain_node_proof_add_facts(
    VolvoxaiV1ShapeDomainNodeProof* message) {
    const SynurangLiteAllocator* allocator;
    VolvoxaiV1ShapeDomainFact* grown;
    size_t capacity;

    if (!message) return NULL;
    allocator = synurang_lite_allocator_or_default(message->_allocator);
    if (message->field_facts.len == message->field_facts.cap) {
        /* The allocator has no realloc, so growth allocates, copies, frees.
         * Doubling keeps repeated appends amortized. */
        capacity = message->field_facts.cap ? message->field_facts.cap * 2u : 4u;
        if (capacity < message->field_facts.cap ||
            capacity > SIZE_MAX / sizeof(*grown)) return NULL;
        grown = (VolvoxaiV1ShapeDomainFact*)allocator->allocate(
            allocator->context, sizeof(*grown) * capacity);
        if (!grown) return NULL;
        memset(grown, 0, sizeof(*grown) * capacity);
        if (message->field_facts.len) {
            memcpy(grown, message->field_facts.data,
                   sizeof(*grown) * message->field_facts.len);
        }
        synurang_lite_release(allocator, message->field_facts.data);
        message->field_facts.data = grown;
        message->field_facts.cap = capacity;
    }
    {
        VolvoxaiV1ShapeDomainFact* slot =
            &message->field_facts.data[message->field_facts.len];
        memset(slot, 0, sizeof(*slot));
        message->field_facts.len++;
        return slot;
    }
}

