static SynurangLiteStatus volvoxai_v1_submit_request_merge_reader(
    VolvoxaiV1SubmitRequest* message,
    SynurangLiteReaderInternal* reader,
    unsigned int message_depth) {
    SynurangLiteStatus status = SYNURANG_LITE_OK;
    uint32_t field_number;
    uint8_t wire_type;
    int tag_result;
    if (!message || !reader) return SYNURANG_LITE_INVALID_ARGUMENT;
    if (message_depth > SYNURANG_LITE_MAX_MESSAGE_DEPTH) {
        return SYNURANG_LITE_MALFORMED;
    }
    (void)status;
    while ((tag_result = sl_read_tag(reader, &field_number, &wire_type)) > 0) {
        switch (field_number) {
            case 1:
                if (!sl_read_int64(
                        reader, wire_type, &message->field_compiled_model_id)) break;
                break;
            case 2:
            {
                const uint8_t* value_data;
                size_t value_len;
                VolvoxaiV1Tensor* item;
                void* appended;
                if (!sl_expect_wire(reader, wire_type, 2) ||
                    !sl_read_slice(reader, &value_data, &value_len)) break;
                status = sl_array_append(
                    message->_allocator,
                    (void**)&message->field_inputs.data,
                    &message->field_inputs.len,
                    &message->field_inputs.cap,
                    sizeof(*message->field_inputs.data),
                    &appended);
                if (status != SYNURANG_LITE_OK) return status;
                item = (VolvoxaiV1Tensor*)appended;
                volvoxai_v1_tensor_init_with_allocator(item, message->_allocator);
                {
                    SynurangLiteReaderInternal value_reader;
                    sl_reader_init(&value_reader, value_data, value_len);
                    status = volvoxai_v1_tensor_merge_reader(
                        item, &value_reader, message_depth + 1);
                }
                if (status != SYNURANG_LITE_OK) return status;
                break;
            }
            case 3:
            {
                const uint8_t* value_data;
                size_t value_len;
                if (!sl_expect_wire(reader, wire_type, 2) ||
                    !sl_read_slice(reader, &value_data, &value_len)) break;
                if (!message->field_options) {
                    message->field_options =
                        (VolvoxaiV1SubmitOptions*)message->_allocator->allocate(
                            message->_allocator->context,
                            sizeof(*message->field_options));
                    if (!message->field_options) return SYNURANG_LITE_OUT_OF_MEMORY;
                    volvoxai_v1_submit_options_init_with_allocator(
                        message->field_options, message->_allocator);
                }
                status = volvoxai_v1_submit_options_merge_at_depth(
                    message->field_options, value_data, value_len,
                    message_depth + 1);
                if (status != SYNURANG_LITE_OK) return status;
                break;
            }
            default:
                if (wire_type == 4 || !sl_skip_field(reader, field_number, wire_type)) {
                    reader->status = SYNURANG_LITE_MALFORMED;
                }
                break;
        }
        if (reader->status != SYNURANG_LITE_OK) break;
    }
    if (tag_result < 0 || reader->status != SYNURANG_LITE_OK) return reader->status;
    return reader->pos == reader->len ? SYNURANG_LITE_OK : SYNURANG_LITE_MALFORMED;
}

SynurangLiteStatus volvoxai_v1_submit_request_decode(
    VolvoxaiV1SubmitRequest* message,
    const uint8_t* data,
    size_t len) {
    VolvoxaiV1SubmitRequest temporary;
    SynurangLiteReaderInternal reader;
    SynurangLiteStatus status;
    if (!message || (!data && len != 0)) return SYNURANG_LITE_INVALID_ARGUMENT;
    volvoxai_v1_submit_request_init_with_allocator(&temporary, message->_allocator);
    sl_reader_init(&reader, data, len);
    status = volvoxai_v1_submit_request_merge_reader(&temporary, &reader, 0);
    if (status != SYNURANG_LITE_OK) {
        volvoxai_v1_submit_request_free(&temporary);
        return status;
    }
    volvoxai_v1_submit_request_free(message);
    *message = temporary;
    return SYNURANG_LITE_OK;
}
VolvoxaiV1Tensor* volvoxai_v1_submit_request_add_inputs(
    VolvoxaiV1SubmitRequest* message) {
    const SynurangLiteAllocator* allocator;
    VolvoxaiV1Tensor* grown;
    size_t capacity;

    if (!message) return NULL;
    allocator = synurang_lite_allocator_or_default(message->_allocator);
    if (message->field_inputs.len == message->field_inputs.cap) {
        /* The allocator has no realloc, so growth allocates, copies, frees.
         * Doubling keeps repeated appends amortized. */
        capacity = message->field_inputs.cap ? message->field_inputs.cap * 2u : 4u;
        if (capacity < message->field_inputs.cap ||
            capacity > SIZE_MAX / sizeof(*grown)) return NULL;
        grown = (VolvoxaiV1Tensor*)allocator->allocate(
            allocator->context, sizeof(*grown) * capacity);
        if (!grown) return NULL;
        memset(grown, 0, sizeof(*grown) * capacity);
        if (message->field_inputs.len) {
            memcpy(grown, message->field_inputs.data,
                   sizeof(*grown) * message->field_inputs.len);
        }
        synurang_lite_release(allocator, message->field_inputs.data);
        message->field_inputs.data = grown;
        message->field_inputs.cap = capacity;
    }
    {
        VolvoxaiV1Tensor* slot =
            &message->field_inputs.data[message->field_inputs.len];
        memset(slot, 0, sizeof(*slot));
        volvoxai_v1_tensor_init_with_allocator(slot, allocator);
        message->field_inputs.len++;
        return slot;
    }
}

