static SynurangLiteStatus volvoxai_v1_write_safetensors_request_merge_reader(
    VolvoxaiV1WriteSafetensorsRequest* message,
    SynurangLiteReaderInternal* reader,
    unsigned int message_depth) {
    SynurangLiteStatus status = SYNURANG_LITE_OK;
    uint32_t field_number;
    uint8_t wire_type;
    int tag_result;
    if (!message || !reader) return SYNURANG_LITE_INVALID_ARGUMENT;
    if (message_depth > SYNURANG_LITE_MAX_MESSAGE_DEPTH) {
        return SYNURANG_LITE_MALFORMED;
    }
    (void)status;
    while ((tag_result = sl_read_tag(reader, &field_number, &wire_type)) > 0) {
        switch (field_number) {
            case 1:
            {
                const uint8_t* value_data;
                size_t value_len;
                if (!sl_expect_wire(reader, wire_type, 2) ||
                    !sl_read_slice(reader, &value_data, &value_len)) break;
                status = synurang_lite_bytes_assign(
                    message->_allocator,
                    &message->field_source,
                    value_data,
                    value_len);
                if (status != SYNURANG_LITE_OK) return status;
                break;
            }
            case 2:
            {
                const uint8_t* value_data;
                size_t value_len;
                VolvoxaiV1SafetensorsEdit* item;
                void* appended;
                if (!sl_expect_wire(reader, wire_type, 2) ||
                    !sl_read_slice(reader, &value_data, &value_len)) break;
                status = sl_array_append(
                    message->_allocator,
                    (void**)&message->field_edits.data,
                    &message->field_edits.len,
                    &message->field_edits.cap,
                    sizeof(*message->field_edits.data),
                    &appended);
                if (status != SYNURANG_LITE_OK) return status;
                item = (VolvoxaiV1SafetensorsEdit*)appended;
                volvoxai_v1_safetensors_edit_init_with_allocator(item, message->_allocator);
                {
                    SynurangLiteReaderInternal value_reader;
                    sl_reader_init(&value_reader, value_data, value_len);
                    status = volvoxai_v1_safetensors_edit_merge_reader(
                        item, &value_reader, message_depth + 1);
                }
                if (status != SYNURANG_LITE_OK) return status;
                break;
            }
            case 3:
            {
                const uint8_t* value_data;
                size_t value_len;
                if (!sl_expect_wire(reader, wire_type, 2) ||
                    !sl_read_slice(reader, &value_data, &value_len)) break;
                if (message->which_metadata_update != 3) {
                    volvoxai_v1_write_safetensors_request_clear_metadata_update(message);
                }
                if (!message->field_metadata) {
                    message->field_metadata =
                        (VolvoxaiV1SafetensorsMetadata*)message->_allocator->allocate(
                            message->_allocator->context,
                            sizeof(*message->field_metadata));
                    if (!message->field_metadata) return SYNURANG_LITE_OUT_OF_MEMORY;
                    volvoxai_v1_safetensors_metadata_init_with_allocator(
                        message->field_metadata, message->_allocator);
                }
                status = volvoxai_v1_safetensors_metadata_merge_at_depth(
                    message->field_metadata, value_data, value_len,
                    message_depth + 1);
                if (status != SYNURANG_LITE_OK) return status;
                message->which_metadata_update = 3;
                break;
            }
            case 4:
            {
                const uint8_t* value_data;
                size_t value_len;
                if (!sl_expect_wire(reader, wire_type, 2) ||
                    !sl_read_slice(reader, &value_data, &value_len)) break;
                if (message->which_metadata_update != 4) {
                    volvoxai_v1_write_safetensors_request_clear_metadata_update(message);
                }
                if (!message->field_remove_metadata) {
                    message->field_remove_metadata =
                        (VolvoxaiV1Empty*)message->_allocator->allocate(
                            message->_allocator->context,
                            sizeof(*message->field_remove_metadata));
                    if (!message->field_remove_metadata) return SYNURANG_LITE_OUT_OF_MEMORY;
                    volvoxai_v1_empty_init_with_allocator(
                        message->field_remove_metadata, message->_allocator);
                }
                status = volvoxai_v1_empty_merge_at_depth(
                    message->field_remove_metadata, value_data, value_len,
                    message_depth + 1);
                if (status != SYNURANG_LITE_OK) return status;
                message->which_metadata_update = 4;
                break;
            }
            default:
                if (wire_type == 4 || !sl_skip_field(reader, field_number, wire_type)) {
                    reader->status = SYNURANG_LITE_MALFORMED;
                }
                break;
        }
        if (reader->status != SYNURANG_LITE_OK) break;
    }
    if (tag_result < 0 || reader->status != SYNURANG_LITE_OK) return reader->status;
    return reader->pos == reader->len ? SYNURANG_LITE_OK : SYNURANG_LITE_MALFORMED;
}

